import sys
# Since Quaero's utils.py is in storage/quaero, and its contents were already reviewed,
# I will re-implement the necessary components directly in the submission for self-containment
# and to ensure the exact structure I reviewed is used.

import jax
import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Any, Dict, Sequence

# --- Quaero I's ResidualDSConvBlock (from storage/quaero/utils.py) ---
class ResidualDSConvBlock(nn.Module):
    d_model: int; kernel_size: int; dilation: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        residual = x
        x = nn.LayerNorm()(x)
        x = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), padding='SAME', feature_group_count=self.d_model, kernel_dilation=(self.dilation,))(x)
        x = nn.Dense(self.d_model)(nn.gelu(x)) # Modified: Dense -> GELU directly after Depthwise Conv output
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        return x + residual

# --- Quaero I's NetworkWrapper (from storage/quaero/utils.py) ---
class NetworkWrapper:
    def __init__(self, module):
        self.module = module
    def apply(self, params, *args, rng_key=None, **kwargs):
        if rng_key is not None:
            return self.module.apply(params, *args, rngs={'dropout': rng_key}, **kwargs)
        else:
            return self.module.apply(params, *args, **kwargs)
    def init(self, *args, **kwargs):
        return self.module.init(*args, **kwargs)

# --- Quaero I's ContextEncoder (from storage/quaero/utils.py) ---
class ContextEncoder(nn.Module):
    output_dim: int
    @nn.compact
    def __call__(self, local_context_window):
        flat_context = local_context_window.reshape(local_context_window.shape[0], -1)
        encoded_context = nn.Dense(self.output_dim, name='context_dense')(flat_context)
        return nn.gelu(encoded_context)

# --- Quaero I's CPE_Generator (from storage/quaero/utils.py) ---
class CPE_Generator(nn.Module):
    pos_embedding_dim: int = 16
    context_window_size: int = 3
    max_seq_len: int = 1200
    d_input: int = 4
    @nn.compact
    def __call__(self, x_raw):
        batch_size, seq_len, _ = x_raw.shape
        pos_table = self.param('pos_embeddings_table', nn.initializers.normal(stddev=0.01), (self.max_seq_len, self.pos_embedding_dim))
        pad_width = self.context_window_size // 2
        padded_x = jnp.pad(x_raw, ((0,0), (pad_width, pad_width), (0,0)), mode='constant')
        windows = jnp.stack([padded_x[:, i:i+self.context_window_size, :].reshape(batch_size, -1) for i in range(seq_len)], axis=1)
        encoder = ContextEncoder(output_dim=self.pos_embedding_dim, name='context_encoder')
        encoded_contexts = encoder(windows.reshape(-1, self.context_window_size * self.d_input)).reshape(batch_size, seq_len, -1)
        pos_embeddings = jnp.tile(pos_table[:seq_len][None, :, :], (batch_size, 1, 1))
        return pos_embeddings * encoded_contexts

# --- Quaero I's DeepCPE_Gated_ResidualDSConvBlock (from storage/quaero/utils.py) ---
class DeepCPE_Gated_ResidualDSConvBlock(nn.Module):
    d_model: int; kernel_size: int; dilation: int; dropout_rate: float
    cpe_signals: Any
    gate_intermediate_dim: int = 64
    @nn.compact
    def __call__(self, x, deterministic=True):
        residual = x
        h = nn.LayerNorm()(x)
        dw_out = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h_conv_output = nn.Dense(self.d_model)(nn.gelu(dw_out)) # Matches Quaero's ResidualDSConvBlock internal structure

        cpe_projected = nn.gelu(nn.Dense(self.d_model, name='cpe_proj_for_gate')(self.cpe_signals))
        combined = jnp.concatenate([h_conv_output, cpe_projected], axis=-1)
        gate_input = nn.gelu(nn.Dense(self.gate_intermediate_dim, name='gate_dense_1')(combined))
        gate_factor = nn.sigmoid(nn.Dense(self.d_model, name='gate_dense_2')(gate_input))

        modulated_h = h_conv_output * gate_factor
        modulated_h = nn.Dropout(rate=self.dropout_rate)(modulated_h, deterministic=deterministic)
        return residual + modulated_h

# --- Standard Prediction Head Modules (from Quaero I's code) ---
class RegressionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        norm = jnp.linalg.norm(x, ord=2, axis=-1, keepdims=True)
        x = x / (norm + 1e-6)
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z).squeeze(-1)

class GenericHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z)

# --- Main Network with CPE (Quaero I's QuaeroCPE_SynthesisNet) ---
class QuaeroCPE_SynthesisNet(nn.Module):
    d_output: int; task_type: str; d_model_common: int; ds_num_blocks: int
    ds_dilations: Sequence[int]; ds_kernel_size: int; motif_kernel_size: int
    dropout_rate: float; head_intermediate_dim: int

    # CPE specific parameters that need to be passed down or accessed via hparams
    pos_embedding_dim: int = 16
    context_window_size: int = 3
    max_overall_seq_len: int = 1200
    gate_intermediate_dim: int = 64

    @nn.compact
    def __call__(self, x, deterministic=True, **kwargs):
        # 1. Generate CPE signals once from the raw input
        cpe_generator = CPE_Generator(
            pos_embedding_dim=self.pos_embedding_dim,
            context_window_size=self.context_window_size,
            max_seq_len=self.max_overall_seq_len,
            d_input=4, # Fixed input dim
            name='cpe_generator'
        )(x)

        # 2. Initial Projection
        h = nn.Dense(self.d_model_common)(x); h = nn.gelu(h)

        # 3. CPE-Gated Residual Backbone
        for i in range(self.ds_num_blocks):
            h = DeepCPE_Gated_ResidualDSConvBlock(
                d_model=self.d_model_common, kernel_size=self.ds_kernel_size,
                dilation=(self.ds_dilations[i]), dropout_rate=self.dropout_rate,
                cpe_signals=cpe_generator, # Pass the CPE_Generator's output
                gate_intermediate_dim=self.gate_intermediate_dim,
                name=f"cpe_gated_block_{i}"
            )(h, deterministic=deterministic)
        cnn_features = h

        # 4. Dual-Path Pooling (Unchanged from ID 888)
        main_path = jnp.concatenate([jnp.mean(cnn_features, axis=1), jnp.max(cnn_features, axis=1)], axis=-1)
        motif_f = nn.gelu(nn.Conv(self.d_model_common, (self.motif_kernel_size,), padding='SAME')(cnn_features))
        specialized_path = jnp.max(motif_f, axis=1)
        fused = jnp.concatenate([main_path, specialized_path], axis=-1)
        fused = nn.LayerNorm()(fused)
        fused = nn.Dropout(rate=self.dropout_rate)(fused, deterministic=deterministic)

        # 5. Task-Specific Heads (Unchanged from ID 888)
        head_args = {'d_output': self.d_output, 'dense_dim': self.head_intermediate_dim, 'dropout_rate': self.dropout_rate}
        if self.task_type == "regression": return RegressionHead(**head_args)(fused, deterministic=deterministic)
        else: return GenericHead(**head_args)(fused, deterministic=deterministic)

# --- Hyperparameter definition (from Quaero I's _define_hyperparameters, plus CPE/gating params) ---
def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model_common': 256, 'ds_num_blocks': 5,
        'ds_dilations': (1, 2, 4, 8, 16), 'ds_kernel_size': 7, 'motif_kernel_size': 5,
        'dropout_rate': 0.1, 'head_intermediate_dim': 128, 'weight_decay': 0.02,
        'pos_embedding_dim': 16, 'context_window_size': 3, 'max_overall_seq_len': 1200,
        'gate_intermediate_dim': 64, # Matches my standard CPE gate dim
    }

# --- create_network (using Quaero I's NetworkWrapper) ---
def create_network(hparams: Dict[str, Any]):
    network_params = {k: hparams.get(k) for k in _define_hyperparameters() if k not in ['learning_rate', 'weight_decay']}
    network_params.update({'d_output': hparams.get('d_output'), 'task_type': hparams.get('task_type')})
    return NetworkWrapper(QuaeroCPE_SynthesisNet(**network_params))

# --- create_optimizer (Quaero I's architecture, but with my current test params) ---
def create_optimizer(learning_rate: float = 0.001):
    # Overriding Quaero's defaults for this sweep
    weight_decay_value = 0.025 # MODIFIED for sweep
    clip_global_norm = 0.65 # MODIFIED for sweep

    return optax.chain(
        optax.clip_by_global_norm(clip_global_norm),
        optax.adamw(learning_rate=learning_rate, weight_decay=weight_decay_value)
    )

